scripts.total_units:
def solve(inputs: dict) -> float:
    A = inputs['A']  # number of lines
    B = inputs['B']  # shifts per line
    C = inputs['C']  # units per shift
    total = A * B * C
    return float(total)

scripts.lcg_generator:
def solve(inputs: dict) -> float:
    X = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    for _ in range(K):
        X = (A * X + B) % M

    return float(X)

scripts.sum_of_squares:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    sum_sq = sum(x**2 for x in values)
    return float(sum_sq)

